import{_ as a,o as i,c as s,a9 as t}from"./chunks/framework.asyjyako.js";const k=JSON.parse('{"title":"Measure an operation","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/quick-tour.md","filePath":"tutorials/quick-tour.md","lastUpdated":null}'),o={name:"tutorials/quick-tour.md"};function r(l,e,n,p,h,d){return i(),s("div",null,[...e[0]||(e[0]=[t(`<p><a id="Bibliography-in-three-small-steps"></a></p><h1 id="Measure-an-operation" tabindex="-1">Measure an operation <a class="header-anchor" href="#Measure-an-operation" aria-label="Permalink to &quot;Measure an operation {#Measure-an-operation}&quot;">​</a></h1><p>Time one operation with its input prepared <strong>before</strong> timing starts. <a id="2.-Run-just-the-export-check"></a></p><p>From the root of the <a href="/PerfChecker/dev/real-packages/index#Get-the-code">versioned example checkout</a>, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/bibliography</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --startup-file=no</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup.jl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --startup-file=no</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.controller/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bibliography</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export_bibtex</span></span></code></pre></div><p>The last command selects one package, one workload and one collector. It prints a report directory at the end:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reports: .../results/benchmark-&lt;suffix&gt;</span></span></code></pre></div><p>Keep that directory: it holds the measurements and the source revisions they describe.</p><h2 id="Swap-the-collector,-keep-the-workload" tabindex="-1">Swap the collector, keep the workload <a class="header-anchor" href="#Swap-the-collector,-keep-the-workload" aria-label="Permalink to &quot;Swap the collector, keep the workload {#Swap-the-collector,-keep-the-workload}&quot;">​</a></h2><p>The operation stays the same; only what is recorded changes.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --startup-file=no</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.controller/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile_alloc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bibliography</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export_bibtex</span></span></code></pre></div><p>Other collectors: <code>benchmark</code>, <code>chairmark</code>, <code>profile</code>, <code>wall_profile</code> (Julia 1.12+). <a id="3.-Compare-versions-and-inspect-the-variation"></a></p><h2 id="Compare-versions" tabindex="-1">Compare versions <a class="header-anchor" href="#Compare-versions" aria-label="Permalink to &quot;Compare versions {#Compare-versions}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --startup-file=no</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.controller/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --startup-file=no</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.controller/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>This runs nine Bibliography versions and four workloads. Earlier versions do not define every workload, so those combinations are <code>unavailable</code> — not slow, failed or zero. <a id="1.-Read-a-measured-result"></a></p><h2 id="Read-a-result" tabindex="-1">Read a result <a class="header-anchor" href="#Read-a-result" aria-label="Permalink to &quot;Read a result {#Read-a-result}&quot;">​</a></h2><ul><li><p>Benchmarks record time, allocated bytes, allocation count and GC time.</p></li><li><p>Compare the <strong>distribution</strong>, not just the median. Overlapping samples are weak evidence.</p></li><li><p>Allocated bytes count Julia allocation activity, not resident memory.</p></li></ul><p><a href="./../guide/understanding-measurements">Understand the result</a> explains these in detail.</p><h2 id="Recorded-examples" tabindex="-1">Recorded examples <a class="header-anchor" href="#Recorded-examples" aria-label="Permalink to &quot;Recorded examples {#Recorded-examples}&quot;">​</a></h2><figure class="doc-screenshot"><iframe class="doc-interactive" src="../examples/bibliography/history/export-time.html" title="Bibliography export medians across nine tagged versions" loading="lazy" sandbox="allow-scripts allow-same-origin allow-downloads"></iframe><figcaption>Native interactive export of medians from 100 samples per tag. Windows · Julia 1.13.0 · one worker thread. Inputs match; dependency revisions follow each tag. Values are in nanoseconds (1,000 ns = 1 µs).</figcaption></figure><p><a href="../examples/bibliography/history/export-time.html">Open the interactive export</a> · <a href="../examples/bibliography/history/export-time.json" download>Download the serialized plot and source revisions</a></p><figure class="doc-screenshot"><iframe class="doc-interactive" src="../examples/bibliography/history/export-samples.html" title="Distribution of 900 recorded Bibliography export timings across nine tagged versions" loading="lazy" sandbox="allow-scripts allow-same-origin allow-downloads"></iframe><figcaption>Native interactive distribution of 900 recorded timings: 100 samples per tag. Boxplots summarize each group; recorded points and slow observations remain available. Points can overlap. This shows variation, not execution order.</figcaption></figure><p><a href="../examples/bibliography/history/export-samples.html">Open the interactive export</a> · <a href="../examples/bibliography/history/export-samples.json" download>Download the serialized plot and source revisions</a></p><p><a id="Choose-your-next-step"></a></p><h2 id="Next" tabindex="-1">Next <a class="header-anchor" href="#Next" aria-label="Permalink to &quot;Next {#Next}&quot;">​</a></h2><ul><li><p><a href="./comparisons">Compare two versions</a> while holding dependencies fixed.</p></li><li><p><a href="./../guide/investigate">Investigate a change</a> with a profile.</p></li></ul>`,26)])])}const u=a(o,[["render",r]]);export{k as __pageData,u as default};
